{
  "checkoutV2": true,
  "theme": "dark",
  "SERVER_TOKEN": "server-token-for-eval"
}

import { flags } from './flags'

const root = document.querySelector<HTMLElement>('#app')

if (root) {
  root.textContent = `${String(flags.checkoutV2)}:${String(flags.theme)}`
}

import assert from 'node:assert/strict'
import { readdir, readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const dist = fileURLToPath(new URL('../examples/consumer/dist/', import.meta.url))
const assets = await readdir(new URL('assets/', `file://${dist}/`))
const scripts = await Promise.all(
  assets.filter((name) => name.endsWith('.js')).map((name) => readFile(`${dist}/assets/${name}`, 'utf8')),
)
const bundle = scripts.join('\n')
const sourceMaps = await Promise.all(
  assets.filter((name) => name.endsWith('.map')).map((name) => readFile(`${dist}/assets/${name}`, 'utf8')),
)
const clientArtifacts = [...scripts, ...sourceMaps].join('\n')

assert.match(bundle, /checkoutV2/)
assert.doesNotMatch(clientArtifacts, /server-token-for-eval/)

import assert from 'node:assert/strict'
import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import { featureFlags } from '../packages/plugin/dist/index.js'
import { createServer } from 'vite'

const root = fileURLToPath(new URL('../examples/consumer/', import.meta.url))
const source = fileURLToPath(new URL('../examples/consumer/flags.json', import.meta.url))
const original = await readFile(source, 'utf8')
const server = await createServer({
  root,
  configFile: false,
  logLevel: 'silent',
  server: { middlewareMode: true },
  plugins: [featureFlags({ source, expose: ['checkoutV2', 'theme'] })],
})

try {
  const first = await server.ssrLoadModule('/src/flags.ts')
  assert.deepEqual(first.flags, { checkoutV2: true, theme: 'dark' })

  const changed = JSON.stringify({
    checkoutV2: false,
    theme: 'light',
    SERVER_TOKEN: 'server-token-for-eval',
  })
  const changeSeen = new Promise((resolve) => server.watcher.once('change', resolve))
  await writeFile(source, changed)
  await changeSeen

  const deadline = Date.now() + 2_000
  let updated
  do {
    updated = await server.ssrLoadModule('/src/flags.ts')
    if (updated.flags.checkoutV2 === false) break
    await new Promise((resolve) => setTimeout(resolve, 25))
  } while (Date.now() < deadline)

  assert.deepEqual(updated.flags, { checkoutV2: false, theme: 'light' })
  assert.doesNotMatch(JSON.stringify(updated.flags), /server-token-for-eval/)
} finally {
  await writeFile(source, original)
  await server.close()
}

import assert from 'node:assert/strict'
import { execFile } from 'node:child_process'
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'

const run = promisify(execFile)
const root = fileURLToPath(new URL('../', import.meta.url))
const temporaryConsumer = await mkdtemp(
  join(tmpdir(), 'frontend-architect-packed-consumer-'),
)

try {
  const { stdout } = await run(
    'npm',
    [
      'pack',
      '--json',
      '--workspace',
      '@frontend-architect-eval/feature-flags',
      '--pack-destination',
      temporaryConsumer,
    ],
    { cwd: root },
  )
  const [manifest] = JSON.parse(stdout)
  const files = new Set(manifest.files.map(({ path }) => path))

  for (const expected of [
    'dist/index.js',
    'dist/index.js.map',
    'dist/index.d.ts',
    'dist/virtual.d.ts',
  ]) {
    assert.ok(files.has(expected), `packed package is missing ${expected}`)
  }

  const vitePackage = JSON.parse(
    await readFile(join(root, 'node_modules/vite/package.json'), 'utf8'),
  )
  await writeFile(
    join(temporaryConsumer, 'package.json'),
    JSON.stringify({ private: true, type: 'module' }),
  )
  await run(
    'npm',
    [
      'install',
      '--ignore-scripts',
      '--no-audit',
      '--no-fund',
      join(temporaryConsumer, manifest.filename),
      `vite@${vitePackage.version}`,
    ],
    { cwd: temporaryConsumer },
  )
  await writeFile(
    join(temporaryConsumer, 'verify.mjs'),
    [
      "import assert from 'node:assert/strict'",
      "import { featureFlags } from '@frontend-architect-eval/feature-flags'",
      "const plugin = featureFlags({ source: new URL('./flags.json', import.meta.url), expose: ['checkoutV2'] })",
      "assert.equal(typeof plugin, 'object')",
      "assert.equal(typeof plugin.resolveId, 'function')",
      "assert.equal(typeof plugin.load, 'function')",
    ].join('\n'),
  )
  await run(process.execPath, ['verify.mjs'], { cwd: temporaryConsumer })
} finally {
  await rm(temporaryConsumer, { recursive: true, force: true })
}

import assert from 'node:assert/strict'
import { fileURLToPath } from 'node:url'

import { featureFlags } from '../packages/plugin/dist/index.js'
import { build } from 'vite'

const root = fileURLToPath(new URL('../examples/consumer/', import.meta.url))
const source = fileURLToPath(new URL('../examples/consumer/flags.json', import.meta.url))

await assert.rejects(
  build({
    root,
    configFile: false,
    logLevel: 'silent',
    plugins: [featureFlags({ source, expose: ['missingFlag'] })],
    build: { write: false },
  }),
  (error) => {
    const message = error instanceof Error ? error.message : String(error)
    return message.includes('missingFlag') && message.includes('flags.json')
  },
)

